mapper.select:
SELECT recognition.id AS recognition_task_id, recognition.recognition_no, task.id AS reading_task_id, task.task_no AS reading_task_no, recognition.image_id, meter.id AS meter_id, meter.meter_no, meter.meter_name, recognition.attempt_no, recognition.status, recognition.recognized_value, recognition.confidence, recognition.model_name, recognition.model_version, recognition.retry_count, recognition.max_retry_count, recognition.version, recognition.started_at, recognition.completed_at, recognition.created_at FROM ai_recognition_task AS recognition INNER JOIN meter_reading_task AS task ON task.id = recognition.reading_task_id INNER JOIN meter ON meter.id = recognition.meter_id WHERE 1 = 1
AND recognition.recognition_no LIKE CONCAT('%', #{recognitionNo}, '%')
AND task.task_no LIKE CONCAT('%', #{readingTaskNo}, '%')
AND meter.meter_no LIKE CONCAT('%', #{meterNo}, '%')
AND recognition.status = #{status}
AND recognition.model_name LIKE CONCAT('%', #{modelName}, '%')
AND recognition.created_at >= #{createdAtStart}
AND recognition.created_at <= #{createdAtEnd}
ORDER BY recognition.created_at DESC, recognition.id DESC

SELECT COALESCE(MAX(attempt_no), 0) + 1
FROM ai_recognition_task
WHERE image_id = #{imageId}
